#!/usr/bin/env python3
"""Combine frozen cohort and Lichess reference-codec measurements."""
import csv,json,platform,subprocess
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'benchmarks-chess-comparison-20261023'
def sha(p):
 import hashlib
 return hashlib.sha256(p.read_bytes()).hexdigest()
coh=json.loads((ROOT/'benchmarks-cohorts-20261023/summary.json').read_text())
protocol=json.loads((ROOT/'benchmarks-cohorts-20261023/protocol.json').read_text())
lichess={r['dataset']:r for r in csv.DictReader((OUT/'lichess-java-currentport/results.csv').open())}
san=json.loads((OUT/'san/manifest.json').read_text())
base_txt=(OUT/'lichess-java/source.txt').read_text().strip()
base_commit=base_txt.split('=',1)[1]
commit='3e815a1ccd294d8f25621c7cb1be96bf21b09209'
java=subprocess.check_output(['java','-version'],stderr=subprocess.STDOUT,text=True).splitlines()[0]
source_hash={}
for tree in ('lichess-java/src/src/main/java','lichess-java-currentport/src/src/main/java'):
 for p in sorted((OUT/tree).rglob('*.java')):source_hash[str(p.relative_to(OUT))]=sha(p)
summary={'date':'2026-10-23','host_cpu':'AMD EPYC 9V74','logical_cpu':1,'java_runtime':java,'lichess_codec':{'upstream':'https://github.com/lichess-org/compression','upstream_head_commit':commit,'upstream_move_list_commit':'c3be3f2','base_java_commit':base_commit,'base_java_commit_date':'2023-07-23','implementation':'Java port of current upstream rank/select move-list operations applied to the older Java source','format_validation':'byte-identical outputs to base implementation for all 15,000 games; all games decode to identical SAN','compile':'Eclipse Compiler for Java 3.37.0, target Java 17','runtime_flags':'-Xms256m -Xmx2g','affinity':'CPU 1 via taskset','measurement':'one full-cohort encode/decode warmup; five timed full-cohort repetitions; median throughput; all games decoded and matched SAN exactly','payload_boundary':'sum of per-game Encoder.encode byte arrays, so each game is byte padded; excludes row lengths, player/event metadata and outer database framing'},'dmg':{'binary_sha256':protocol['native_sha256'],'mode':'R19 builtin mode3 g10static','measurement':'existing native speed confirmation from the same frozen 5,000-game cohorts, CPU 1; framed bits/ply includes D19 archive framing; payload bits/ply excludes framing'},'datasets':{},'source_hashes':source_hash,'chessbook_public_claim':{'reported_bits_per_move':3.7,'source':'https://chessbook.com/blog/compressing-chess-moves-even-further','scope':'opening-line compression use case; public writeup describes legal-move ranking, opening-specific tuned piece-square tables, and arithmetic coding but does not publish executable/source code for the 3.7-bit codec','locally_executed':False}}
lines=['# Lichess / Chessbook과 DMG-Entropy 비교','', '측정일: 2026-10-23. 세 집단은 고정된 동일 5,000판 코호트이며, 합계 15,000판/2,547,354 반수다. Lichess의 공개 코덱과 현재 upstream의 rank/select 최적화를 Java로 포팅해 현 CPU 1에서 실행했다. 출력이 이전 공개 구현과 15,000판 모두 바이트 단위로 같고, 복호화도 전부 일치했다. Chessbook의 3.7 bit/수 코덱은 공개 소스나 실행 파일이 없어 직접 실행하지 못했다.','', '## 결과','', '| 집단 | 기보/반수 | DMG 비트/수 (payload / framed) | Lichess 비트/수 | DMG 인코딩 수/초 | Lichess 인코딩 수/초 | DMG 디코딩 수/초 | Lichess 디코딩 수/초 |','|---|---:|---:|---:|---:|---:|---:|---:|---:|']
for group in ('general','elite','random'):
 d=coh[group];dm=d['overall'];l=lichess[group]
 payload=dm['payload_bit_per_ply']['value'];framed=dm['framed_bit_per_ply']['value'];lb=float(l['bits_per_ply'])
 de=dm['native_encode_plies_per_second']['value'];dd=dm['native_decode_plies_per_second']['value'];le=float(l['encode_plies_s']);ld=float(l['decode_plies_s'])
 summary['datasets'][group]={'games':d['games'],'plies':d['plies'],'source_sha256':san[group]['input_sha256'],'san_sha256':san[group]['san_sha256'],'dmg_payload_bits_per_ply':payload,'dmg_framed_bits_per_ply':framed,'lichess_emitted_byte_bits_per_ply':lb,'lichess_bytes':int(l['payload_bytes']),'dmg_encode_plies_per_second':de,'lichess_encode_plies_per_second':le,'lichess_encode_speedup':le/de,'dmg_decode_plies_per_second':dd,'lichess_decode_plies_per_second':ld,'lichess_decode_speedup':ld/dd,'lichess_vs_dmg_framed_size_percent':100*(lb/framed-1),'lichess_timing_encode_ms':l['encode_ms'],'lichess_timing_decode_ms':l['decode_ms']}
 lines.append(f"| {group} | {d['games']:,} / {d['plies']:,} | {payload:.3f} / **{framed:.3f}** | {lb:.3f} | {de:,.0f} | {le:,.0f} (**{le/de:.1f}×**) | {dd:,.0f} | {ld:,.0f} (**{ld/dd:.1f}×**) |")
lines += ['', 'DMG의 수치와 Lichess의 바이트 수는 포장 경계가 완전히 같지 않다. DMG framed 값은 전체 D19 파일의 헤더·구조·체크섬을 포함한다. Lichess 값은 각 기보를 독립 인코딩한 바이트 배열을 합산해 게임마다 끝 바이트까지 센 값이며, 행 길이와 플레이어·대회 정보 등 데이터베이스 필드는 뺐다. 이 조건에서도 세 집단 모두 DMG 파일의 framed 비트/수가 더 낮게 나왔다. 정확한 비교를 위해 두 payload 수치와 DMG framed 수치를 모두 보존했다.','', '속도는 같은 EPYC 9V74 논리 CPU 1에 고정했다. Lichess 코드는 OpenJDK 17에서 측정했다. 현재 upstream의 move-list rank/select 알고리즘을 Java로 옮겨 2023년 Java 기준 구현에 적용했으며, 나머지 최신 Scala writer 최적화는 포팅하지 않았다. 코덱에 기보별 SAN 배열을 메모리에서 전달하며, 전체 코호트 워밍업 후 다섯 번 처리한 중앙 처리량이다. 15,000판 모두 인코딩 후 정확히 SAN으로 복원됐다. DMG 속도는 기존 native CLI 확인 자료에서 가져왔다. Lichess 측정은 PGN 파싱 및 UCI→SAN 준비를 제외하고, DMG native CLI의 입력 경로와 완전히 같은 타이밍 경계는 아니므로 속도 배수는 같은 조건의 정식 순위로 해석하면 안 된다.','', '## Chessbook 수치의 범위','', 'Chessbook 글은 법적 수를 생성하고 순위를 매긴 뒤 수 인덱스를 부호화하는 구조, Lichess식 Huffman 대신 산술 부호화를 쓴 점, 오프닝 라인용 기물-제곱표를 따로 튜닝한 점을 설명한다. 제목의 3.7 bit/수는 Chessbook의 오프닝 라인 압축 결과다. 공개 글에는 그 코덱의 실행 가능한 소스/바이너리와 동일한 15,000판에서의 속도 결과가 없다. 따라서 3.7을 이 표의 실측 칸에 넣거나, 15,000판 전체 기보 결과라고 부르지 않았다.','', '## 재현 및 한계','', f'- 데이터 입력은 이전에 고정한 5,000판 일반인, 5,000판 Elo 2600 이상 엘리트, 5,000판 균등 합법 수 랜덤 집단이다. 원본 UCI 입력 SHA-256은 `san/manifest.json`에 있다. SAN 변환 파일 해시도 같은 manifest에 기록했다.',f'- Lichess upstream HEAD는 `{commit}`이며, move-list 최적화는 `c3be3f2`의 rank/select 방식을 포팅했다. 기반 Java 구현은 `{base_commit}`이다. 현재 Scala writer의 다른 최신 최적화는 포함하지 않아, Lichess 최신 빌드 자체의 실측 속도라고 해석하지 않는다. 압축 바이트는 15,000판 전부 기반 구현과 일치했다.', '- 최종 Lichess 반복 5회의 전체 시간을 `lichess-java-currentport/results.csv`에 남겼다. 이전 Java baseline은 `lichess-java/results.csv`에 보존했다. 두 구현의 바이트 일치 검사는 `runner/CompareLichess.java`로 수행했다. 첫 전체 코호트 워밍업은 별도이며 시간 통계에 넣지 않았다. outlier 삭제는 하지 않았다.', '- DMG의 95% block bootstrap 신뢰구간은 원래 cohort 보고서에 있다. Lichess는 전체 데이터 반복 처리 5회 중앙값만 측정했고 독립 원본 데이터 블록별 신뢰구간을 계산하지 않았다.', '- Chessbook 비교를 완성하려면 3.7 bit/수 방식의 실행 코드나 동일 데이터셋에서 내보낸 결과물이 필요하다.', '', '## 출처', '', '- Lichess compression repository: https://github.com/lichess-org/compression', '- Lichess encoding design: https://lichess.org/@/lichess/blog/developer-update-275-improved-game-compression/Wqa7GiAA', '- Chessbook 3.7-bit article: https://chessbook.com/blog/compressing-chess-moves-even-further', '- Chessbook earlier SAN codec article: https://chessbook.com/blog/compressing-chess-moves', '']
(OUT/'report.md').write_text('\n'.join(lines))
(OUT/'README-Lichess-Chessbook-Compare-20261023-KO.md').write_text('\n'.join(lines))
(OUT/'summary.json').write_text(json.dumps(summary,indent=2)+'\n')
print(OUT/'report.md')
print(json.dumps({k:{'DMGframed':v['dmg_framed_bits_per_ply'],'Lichess':v['lichess_emitted_byte_bits_per_ply'],'enc_x':v['lichess_encode_speedup'],'dec_x':v['lichess_decode_speedup']} for k,v in summary['datasets'].items()},indent=2))
